PGPASS=[REDACTED:value] /tmp/pgpass.txt); APPSEC=$(cat /tmp/appsecret.txt)
CONN="redu-425516:us-central1:umami-db-547c"
DBURL="postgresql://postgres:[REDACTED:conn-password]@localhost/umami?host=/cloudsql/${CONN}"
cat > /tmp/run.json <<EOF
{
  "ingress": "INGRESS_TRAFFIC_ALL",
  "launchStage": "GA",
  "template": {
    "serviceAccount": "299813327652-compute@developer.gserviceaccount.com",
    "timeout": "300s",
    "maxInstanceRequestConcurrency": 80,
    "scaling": {"minInstanceCount": 1, "maxInstanceCount": 3},
    "volumes": [
      {"name": "cloudsql", "cloudSqlInstance": {"instances": ["${CONN}"]}}
    ],
    "containers": [
      {
        "image": "us-central1-docker.pkg.dev/redu-425516/umami-remote/umami-software/umami@sha256:fa32d116cf20cad52cbc3fad9a63b46e7fa02299d8f967168eb453d49c476b4a",
        "ports": [{"name": "http1", "containerPort": 3000}],
        "env": [
          {"name": "DATABASE_URL", "value": "${DBURL}"},
          {"name": "DATABASE_TYPE", "value": "postgresql"},
          {"name": "APP_SECRET", "value": "${APPSEC}"},
          {"name": "HOSTNAME", "value": "0.0.0.0"}
        ],
        "resources": {"limits": {"cpu": "1", "memory": "1Gi"}, "cpuIdle": false, "startupCpuBoost": true},
        "volumeMounts": [{"name": "cloudsql", "mountPath": "/cloudsql"}],
        "startupProbe": {
          "httpGet": {"path": "/api/heartbeat", "port": 3000},
          "initialDelaySeconds": 10,
          "periodSeconds": 10,
          "timeoutSeconds": 5,
          "failureThreshold": 23
        }
      }
    ]
  }
}
EOF
curl -s -X POST -H "Authorization: Bearer $T" -H "Content-Type: application/json" \
 "https://run.googleapis.com/v2/projects/$P/locations/us-central1/services?serviceId=umami-acs547c2aaa" -d @/tmp/run.json | jq -c '{name,done,error}'

